#Requires -Version 7.0
#Requires -Modules @{ ModuleName = 'Pester'; ModuleVersion = '5.0.0' }
# docs/script-status.md is generated by scripts/deploy/common/New-DeployScriptStatus.ps1. Like the variables reference, a test
# runs the generator with -Check and fails when the page on disk is stale. The rows are checked against a made-up deploy folder.
# Run: Invoke-Pester ./tests/deploy-scripts

[Diagnostics.CodeAnalysis.SuppressMessageAttribute('PSReviewUnusedParameter', '', Justification = 'Pester blocks.')]
[Diagnostics.CodeAnalysis.SuppressMessageAttribute('PSUseShouldProcessForStateChangingFunctions', '', Justification = 'Test helpers.')]
param()

BeforeAll {
    $script:Repo = [System.IO.Path]::GetFullPath([System.IO.Path]::Combine($PSScriptRoot, '..', '..'))
    $script:Script = [System.IO.Path]::Combine($script:Repo, 'scripts', 'deploy', 'common', 'New-DeployScriptStatus.ps1')
    $script:Page = [System.IO.Path]::Combine($script:Repo, 'docs', 'script-status.md')

    function Invoke-Status {
        param([string[]]$Arguments)
        $output = & pwsh -NoProfile -NonInteractive -File $script:Script @Arguments 2>&1 | Out-String
        [pscustomobject]@{ Code = $LASTEXITCODE; Output = $output }
    }

    function New-TempFolder {
        $p = Join-Path ([System.IO.Path]::GetTempPath()) ('st-' + [guid]::NewGuid().ToString('N').Substring(0, 8))
        New-Item -ItemType Directory -Path $p | Out-Null
        $p
    }

    function Write-File([string]$Path, [string]$Text) {
        New-Item -ItemType Directory -Path (Split-Path $Path -Parent) -Force | Out-Null
        Set-Content -LiteralPath $Path -Value $Text
    }

    $script:RealScript = '# a real script'
    $script:PlaceholderText = "Import-Module x`nInvoke-DeploymentOrchestrated -TaskPath 't'"
    $script:PlaceholderAz = "Import-Module x`nInvoke-DeploymentAzCliPowerShell -TaskPath 't'"
}

Describe 'docs/script-status.md' {
    It 'is current: New-DeployScriptStatus.ps1 -Check finds nothing stale' {
        $r = Invoke-Status -Arguments @('-Check')
        $r.Code | Should -Be 0 -Because $r.Output
        $r.Output | Should -Match 'is current'
    }

    It 'fails -Check when the page is stale' {
        $tmp = New-TempFolder
        try {
            $stale = Join-Path $tmp 'script-status.md'
            $text = (Get-Content -LiteralPath $script:Page -Raw).Replace("`r`n", "`n")
            $text.Contains('| not built |') | Should -BeTrue
            $changed = $text.Replace('| not built |', '| built |')
            Set-Content -LiteralPath $stale -Value $changed -NoNewline
            $r = Invoke-Status -Arguments @('-Check', '-OutputPath', $stale)
            $r.Code | Should -Be 1
            $r.Output | Should -Match 'out of date'
            (Get-Content -LiteralPath $stale -Raw) | Should -BeExactly $changed -Because '-Check writes nothing'
        }
        finally { Remove-Item -LiteralPath $tmp -Recurse -Force -ErrorAction SilentlyContinue }
    }

    It 'fails -Check when the page is missing' {
        $r = Invoke-Status -Arguments @('-Check', '-OutputPath', (Join-Path ([System.IO.Path]::GetTempPath()) ('missing-' + [guid]::NewGuid().ToString('N') + '.md')))
        $r.Code | Should -Be 1
        $r.Output | Should -Match "doesn't exist"
    }

    It 'has a row for every task folder and links from the README' {
        $page = Get-Content -LiteralPath $script:Page -Raw
        $catalogue = Import-PowerShellDataFile -LiteralPath ([System.IO.Path]::Combine($script:Repo, 'scripts', 'deploy', 'common', 'TaskCatalogue.psd1'))
        foreach ($task in $catalogue.Tasks) {
            $rest = $task.Path.Substring($task.Path.IndexOf('/') + 1)
            $page | Should -Match ([regex]::Escape('| `' + $rest + '` |'))
        }
        (Get-Content -LiteralPath ([System.IO.Path]::Combine($script:Repo, 'README.md')) -Raw) | Should -Match 'docs/script-status\.md'
    }
}

Describe 'New-DeployScriptStatus.ps1 on a made-up deploy folder' {
    BeforeAll {
        $script:Tmp = New-TempFolder
        $script:Deploy = Join-Path $script:Tmp 'deploy'
        New-Item -ItemType Directory -Path (Join-Path $script:Deploy 'common') -Force | Out-Null
        # 01-s/phase-01-p/task-01-azure: real PowerShell, Azure CLI placeholder only
        Write-File (Join-Path $script:Deploy '01-s/phase-01-p/task-01-azure/powershell/Real.ps1') $script:RealScript
        Write-File (Join-Path $script:Deploy '01-s/phase-01-p/task-01-azure/azurecli/az-one.ps1') $script:PlaceholderAz
        # task-02-both: real PowerShell and real Azure CLI
        Write-File (Join-Path $script:Deploy '01-s/phase-01-p/task-02-both/powershell/Real.ps1') $script:RealScript
        Write-File (Join-Path $script:Deploy '01-s/phase-01-p/task-02-both/azurecli/az-two.ps1') $script:RealScript
        # task-02-both also holds an older Bash script; a bash folder with no script (task-01-azure) does not count
        Write-File (Join-Path $script:Deploy '01-s/phase-01-p/task-02-both/bash/az-two.sh') '#!/usr/bin/env bash'
        Write-File (Join-Path $script:Deploy '01-s/phase-01-p/task-01-azure/bash/.gitkeep') ''
        # task-03-onprem: PowerShell placeholder only, Azure CLI does not apply
        Write-File (Join-Path $script:Deploy '02-t/phase-01-q/task-03-onprem/powershell/Invoke-X-Orchestrated.ps1') $script:PlaceholderText
        # task-04-unclear: nothing built, Azure CLI not decided
        Write-File (Join-Path $script:Deploy '02-t/phase-01-q/task-04-unclear/powershell/.gitkeep') ''
        # ... and two placeholders that do not call an Invoke-Deployment function: one has only the comment line, one ends directly
        Write-File (Join-Path $script:Deploy '02-t/phase-01-q/task-04-unclear/powershell/Marked.ps1') "#Requires -Version 7.0`n# PLACEHOLDER: this script does not do the task.`nexit 3"
        Write-File (Join-Path $script:Deploy '02-t/phase-01-q/task-04-unclear/azurecli/az-direct.ps1') "Import-Module x`nStop-DeploymentPlaceholder -TaskPath 't' -Kind 'Azure CLI'"
        $script:Catalogue = Join-Path $script:Tmp 'catalogue.psd1'
        Write-File $script:Catalogue @"
@{
    SchemaVersion = 1
    Tasks = @(
        @{ Path = '01-s/phase-01-p/task-01-azure'; AzureCli = 'yes'; Reason = 'r' }
        @{ Path = '01-s/phase-01-p/task-02-both'; AzureCli = 'yes'; Reason = 'r' }
        @{ Path = '02-t/phase-01-q/task-03-onprem'; AzureCli = 'no'; Reason = 'r' }
        @{ Path = '02-t/phase-01-q/task-04-unclear'; AzureCli = 'unclear'; Reason = 'Not decided yet.' }
    )
}
"@
        $script:Out = Join-Path $script:Tmp 'status.md'
        $script:Run = Invoke-Status -Arguments @('-DeployRoot', $script:Deploy, '-TaskCatalogPath', $script:Catalogue, '-OutputPath', $script:Out)
        $script:Text = if (Test-Path $script:Out) { (Get-Content -LiteralPath $script:Out -Raw).Replace("`r`n", "`n") } else { '' }
    }

    AfterAll { Remove-Item -LiteralPath $script:Tmp -Recurse -Force -ErrorAction SilentlyContinue }

    It 'runs' {
        $script:Run.Code | Should -Be 0 -Because $script:Run.Output
    }

    It 'calls an Azure CLI placeholder "not built", never "built"' {
        $script:Text | Should -Match ([regex]::Escape('| `phase-01-p/task-01-azure` | built | not built | yes |'))
    }

    It 'calls a real Azure CLI script "built"' {
        $script:Text | Should -Match ([regex]::Escape('| `phase-01-p/task-02-both` | built | built | yes |'))
    }

    It 'calls a task that does not act on Azure "not applicable", and a PowerShell placeholder "not built"' {
        $script:Text | Should -Match ([regex]::Escape('| `phase-01-q/task-03-onprem` | not built | not applicable | no |'))
    }

    It 'flags a task that is not decided and lists why; a placeholder by comment line or by a direct stop is not built' {
        $script:Text | Should -Match ([regex]::Escape('| `phase-01-q/task-04-unclear` | not built | not built | unclear |'))
        $script:Text | Should -Match ([regex]::Escape('| `02-t/phase-01-q/task-04-unclear` | Not decided yet. |'))
    }

    It 'lists the task folders that still hold an older Bash script, and no others' {
        $script:Text | Should -Match ([regex]::Escape('Task folders that still hold an older Bash script: 1.'))
        $script:Text | Should -Match '(?m)^## Older Bash scripts$'
        $script:Text | Should -Match ([regex]::Escape('- `01-s/phase-01-p/task-02-both`'))
        $script:Text | Should -Not -Match ([regex]::Escape('- `01-s/phase-01-p/task-01-azure`'))
    }

    It 'groups the rows by stage' {
        $script:Text | Should -Match '(?m)^## 01-s$'
        $script:Text | Should -Match '(?m)^## 02-t$'
    }

    It 'writes the same page again, byte for byte' {
        $again = Join-Path $script:Tmp 'status-again.md'
        (Invoke-Status -Arguments @('-DeployRoot', $script:Deploy, '-TaskCatalogPath', $script:Catalogue, '-OutputPath', $again)).Code | Should -Be 0
        (Get-Content -LiteralPath $again -Raw) | Should -BeExactly (Get-Content -LiteralPath $script:Out -Raw)
    }

    It 'stops when a task folder is not in the catalogue' {
        Write-File (Join-Path $script:Deploy '02-t/phase-01-q/task-05-new/powershell/Real.ps1') $script:RealScript
        $r = Invoke-Status -Arguments @('-DeployRoot', $script:Deploy, '-TaskCatalogPath', $script:Catalogue, '-OutputPath', (Join-Path $script:Tmp 'x.md'))
        Remove-Item -LiteralPath (Join-Path $script:Deploy '02-t/phase-01-q/task-05-new') -Recurse -Force
        $r.Code | Should -Be 1
        $r.Output | Should -Match "Task folder '02-t/phase-01-q/task-05-new' is not in"
    }

    It 'stops when a catalogue entry has no folder' {
        Remove-Item -LiteralPath (Join-Path $script:Deploy '02-t/phase-01-q/task-04-unclear') -Recurse -Force
        $r = Invoke-Status -Arguments @('-DeployRoot', $script:Deploy, '-TaskCatalogPath', $script:Catalogue, '-OutputPath', (Join-Path $script:Tmp 'y.md'))
        $r.Code | Should -Be 1
        $r.Output | Should -Match "Catalogue entry '02-t/phase-01-q/task-04-unclear' has no task folder"
    }
}
